  ln=f(r'Layer norm per layer: \[([^\]]+)\]');d=f(r'- Depth: (\d+)');w=f(r'- Width: (\d+)');o=f(r'- Optimizer: (\w+)');lr=f(r'- Learning rate: ([\deE.\-]+)');m=f(r'- Momentum: ([\d.]+)')
  if not all([ln,d,w,o,lr]):continue
  out.append(dict(letter=s[0],depth=int(d),width=int(w),residual=f(r'Residual connections: (\w+)')=='True',ln=[x.strip()=='True' for x in ln.split(',')],activation=f(r'- Activation: (\w+)'),opt=o,lr=float(lr),m=float(m or 0)))
 return out
for r in h:
 if r['family']!='xor_classification':continue
 cs=parse(r)
 if len(cs)>1 and all(c['opt']=='SGD' for c in cs):
  print(r['question_id'],r['answer'], re.search(r'training_steps: (\d+)',r['question']).group(1),[(c['letter'],c['depth'],c['width'],c['residual'],sum(c['ln']),c['activation'],c['lr'],c['m']) for c in cs])
